const COBROS = $('Cobros del extracto').all().map((i) => i.json);

const norm = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const cents = (v) => Math.round(Number(v) * 100);
const eur = (c) => (c / 100).toFixed(2);
const STOP = new Set(['SL', 'SA', 'SLU', 'SAU', 'GMBH', 'UAB', 'LOGISTICS', 'LOGISTIC', 'LOGISTICA', 'LOGIS', 'TRANSPORTES', 'TRANSPORTE', 'TRANS', 'SPEDITION', 'SPEDITIONS', 'SPEDITIONSGES', 'SPEDIT', 'GROUP', 'FREIGHT', 'INTERNATIONAL', 'HERMANOS', 'NACHFOLGER', 'DISTRIBUCION', 'OPERADOR', 'EUROPE', 'SOCIEDAD']);
const tokens = (s) => String(s || '').toUpperCase().normalize('NFD').replace(/[^A-Z0-9]+/g, ' ').split(' ').filter((t) => t.length >= 4 && !STOP.has(t));
const ES_ENTIDAD = /CAIXABANK|BANCO|BANK|FACTORING|CONFIRMING|BBVA|SANTANDER|SABADELL|BANKINTER|CAJAMAR/i;

const r = $input.first().json;
if (!r || r.success !== true || !Array.isArray(r.efectos)) {
  throw new Error('No se pudo leer la cartera: ' + JSON.stringify(r).slice(0, 300));
}
// Más antiguos primero: ante empates se propone el vencimiento más antiguo
const efectos = r.efectos.slice().sort((a, b) => String(a.FechaVencimiento).localeCompare(String(b.FechaVencimiento)));
const porFactura = {};
const porCliente = {};
for (const e of efectos) {
  const k = norm(e.Factura);
  (porFactura[k] = porFactura[k] || []).push(e);
  (porCliente[e.Cliente] = porCliente[e.Cliente] || []).push(e);
}
// Cuántos ingresos citan cada factura (para avisar de pagos repetidos/parciales)
const citas = {};
for (const c of COBROS) { for (const f of c.facturas) { citas[norm(f)] = (citas[norm(f)] || 0) + 1; } }

const descr = (e) => e.Cliente + ' ' + e.NombreCliente + ' | ' + e.Factura + ' | ' + eur(cents(e.Importe)) + ' | vto ' + String(e.FechaVencimiento).slice(0, 10);

function subconjuntos(lista, objetivo, maxTam, maxRes) {
  const res = [];
  const rec = (i, acum, suma) => {
    if (res.length >= maxRes) return;
    if (suma === objetivo && acum.length > 0) { res.push(acum.slice()); return; }
    if (acum.length >= maxTam || suma > objetivo) return;
    for (let j = i; j < lista.length; j++) {
      acum.push(lista[j]);
      rec(j + 1, acum, suma + cents(lista[j].Importe));
      acum.pop();
      if (res.length >= maxRes) return;
    }
  };
  rec(0, [], 0);
  return res;
}

const out = [];
for (const c of COBROS) {
  const obj = cents(c.importe);
  let estado = 'SIN_CASAR';
  let detalle = '';
  let propuesta = [];
  let resuelto = false;

  // Nivel 1: facturas citadas en el concepto del banco
  if (c.facturas.length > 0) {
    const halladas = [];
    const faltan = [];
    for (const f of c.facturas) {
      const l = porFactura[norm(f)];
      if (l) { for (const e of l) halladas.push(e); } else { faltan.push(f); }
    }
    const repetida = c.facturas.filter((f) => citas[norm(f)] > 1);
    const avisoRep = repetida.length ? ' Factura citada en varios ingresos: ' + repetida.join(', ') + '.' : '';
    if (halladas.length === 0) {
      // Si el banco cita facturas y ninguna esta pendiente, NO se busca otra combinacion por nombre:
      // daria falsos positivos. Lo normal es que ya esten cobradas en T2000.
      estado = 'CITADAS_NO_PENDIENTES';
      resuelto = true;
      detalle = 'Facturas citadas sin efecto pendiente en cartera (probablemente ya cobradas/aplicadas en T2000, o referencia ajena): ' + faltan.join(', ') + '.' + avisoRep;
    } else {
      const suma = halladas.reduce((s, e) => s + cents(e.Importe), 0);
      const nota = (faltan.length ? ' No pendientes: ' + faltan.join(', ') + '.' : '') + avisoRep;
      if (suma === obj) {
        estado = 'SEGURO'; propuesta = halladas; resuelto = true;
        detalle = 'Facturas citadas y suma de importes coinciden.' + nota;
      } else {
        const subs = subconjuntos(halladas, obj, 6, 3);
        if (subs.length >= 1) {
          estado = 'PROBABLE'; propuesta = subs[0]; resuelto = true;
          detalle = 'El importe coincide con parte de las facturas citadas.' + nota;
        } else {
          estado = 'IMPORTE_NO_CUADRA'; propuesta = halladas; resuelto = true;
          detalle = 'Facturas citadas suman ' + eur(suma) + ' y el ingreso es ' + eur(obj) + ' (dif ' + eur(obj - suma) + ').' + nota;
        }
      }
    }
  }

  // Ordenante que es una entidad financiera (factoring, confirming, anticipo): no se cruza por nombre
  if (!resuelto && ES_ENTIDAD.test(c.contraparte)) {
    estado = 'ENTIDAD_FINANCIERA';
    resuelto = true;
    detalle = 'El ordenante es una entidad financiera (posible factoring/confirming/anticipo): hay que ver a que clientes corresponde.';
  }

  // Nivel 2 (solo si el banco no cita facturas): nombre del ordenante + importe exacto
  if (!resuelto) {
    const tk = tokens(c.contraparte);
    let mejor = [];
    let mejorScore = 0;
    for (const cli of Object.keys(porCliente)) {
      const lista = porCliente[cli];
      const tn = tokens(lista[0].NombreCliente + ' ' + lista[0].NombreClienteCartera);
      const sc = tk.filter((t) => tn.some((n) => n === t || (t.length >= 5 && n.startsWith(t)))).length;
      if (sc > mejorScore) { mejorScore = sc; mejor = [cli]; } else if (sc === mejorScore && sc > 0) { mejor.push(cli); }
    }
    const candidatos = [];
    for (const cli of mejor) {
      for (const s of subconjuntos(porCliente[cli], obj, 6, 3)) candidatos.push(s);
    }
    if (candidatos.length === 1) {
      estado = 'PROBABLE'; propuesta = candidatos[0];
      detalle += 'Cliente por nombre del ordenante + importe exacto.';
    } else if (candidatos.length > 1) {
      estado = 'AMBIGUO'; propuesta = candidatos[0];
      detalle += 'Varias combinaciones posibles (se propone la de vencimiento mas antiguo, confirmar): ' + candidatos.map((s) => s.map((e) => e.Factura).join('+')).join(' / ');
    } else if (mejor.length > 0) {
      estado = 'CLIENTE_SIN_IMPORTE';
      propuesta = [];
      const pend = mejor.reduce((a, cli) => a.concat(porCliente[cli]), []);
      detalle += 'Cliente probable: ' + pend[0].NombreCliente + ' (' + mejor.join(',') + '), ' + pend.length + ' efectos pendientes por ' + eur(pend.reduce((s, e) => s + cents(e.Importe), 0)) + ' en total; ninguna combinacion suma el ingreso (pago parcial, abono descontado o ya aplicado). Pendientes: ' + pend.slice(0, 6).map((e) => e.Factura + ' ' + eur(cents(e.Importe))).join('; ');
    } else {
      const mismos = efectos.filter((e) => cents(e.Importe) === obj).slice(0, 5);
      if (mismos.length > 0) {
        estado = 'POSIBLE_POR_IMPORTE'; propuesta = mismos;
        detalle += 'Confianza BAJA: ningun cliente coincide por nombre; solo hay ' + mismos.length + ' efecto(s) con ese importe exacto.';
      } else {
        detalle += 'Sin cliente por nombre ni efecto con ese importe: probablemente ya cobrado o falta la factura.';
      }
    }
  }

  out.push({ json: {
    estado: estado,
    fecha: c.fecha,
    importe: c.importe,
    ordenante_banco: c.contraparte,
    facturas_citadas: c.facturas.join(', '),
    detalle: detalle.trim(),
    propuesta: propuesta.map(descr),
    claves_cartera: propuesta.map((e) => e.ClaveCartera),
    total_propuesta: eur(propuesta.reduce((s, e) => s + cents(e.Importe), 0)),
    id_movimiento: c.id
  } });
}
out.push({ json: { estado: '_RESUMEN', efectos_pendientes_leidos: efectos.length, clientes_con_pendientes: Object.keys(porCliente).length } });
return out;

